"""Seating charts: students sorted by name, in rows."""

from typing import List

from rosterkit.models import Student
from rosterkit.errors import ProjectError

def _sort_key(student: Student) -> tuple:
    return (student.last_name.lower(), student.first_name.lower())

def _chunks(items: list, size: int) -> list:
    return [
        items[pos:pos + size]
        for pos in range(0, len(items), size)
    ]

def _number_rows(rows: list) -> List[str]:
    lines = []
    for num, row in enumerate(rows, 1):
        names = [stud.display_name for stud in row]
        lines.append(f"Row {num}: " + " | ".join(names))
    return lines

# ---
def seat_rows(students: List[Student], seats: int) -> List[str]:
    if seats < 1 or not students:
        raise ProjectError("need students and a seat count")
    ordered = sorted(students, key=_sort_key)
    return _number_rows(_chunks(ordered, seats))

