import unittest

from rosterkit.seating import seat_rows
from rosterkit.models import Student
from rosterkit.errors import ProjectError

def make(last, first):
    return Student("id-" + last, last, first, "A")

class SeatingTests(unittest.TestCase):
    def setUp(self):
        self.roster = [
            make("Halloway", "Juno"),
            make("Dunmere", "Piet"),
            make("Abbot", "Rhea")
        ]

    def test_sorted_rows(self):
        self.assertEqual(seat_rows(self.roster, 2), [
            "Row 1: Abbot, Rhea | Dunmere, Piet",
            "Row 2: Halloway, Juno"
        ])

    def test_single_row(self):
        self.assertEqual(len(seat_rows(self.roster, 5)), 1)

    def test_bad_seat_count(self):
        for seats in (0, -3):
            with self.assertRaises(ProjectError):
                seat_rows(self.roster, seats)

    def test_no_students(self):
        with self.assertRaises(ProjectError):
            seat_rows([], 3)
